"""Normalize release records at the input boundary."""

MISSING = object()


class JournalError(ValueError):
    pass


def _change_id(value):
    return isinstance(value, str) and bool(value)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not _change_id(row.get("id"))
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        raw = row.get("depends_on", [])
        if not isinstance(raw, list) or not all(_change_id(dep) for dep in raw):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": frozenset(raw),
        }
        seen = changes.get(change["id"], MISSING)
        if seen is MISSING:
            changes[change["id"]] = change
        elif seen != change:
            raise JournalError("conflicting-change")
    return list(changes.values())


def read_applied(value):
    if value is MISSING:
        return set()
    if not isinstance(value, list) or not all(_change_id(item) for item in value):
        raise JournalError("invalid-change")
    return set(value)

