"""Compose policy and journal data into a plan."""
import heapq

from journal import MISSING, JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topo_order(changes):
    """Deterministic topological order; lexicographic ID tie-breaking."""
    by_id = {row["id"]: row for row in changes}
    indegree = {}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in by_id:
                raise JournalError("unknown-dependency")
        indegree[row["id"]] = len(row["depends_on"])
    for row in changes:
        for dep in row["depends_on"]:
            dependents[dep].append(row["id"])

    ready = [ident for ident, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        ident = heapq.heappop(ready)
        order.append(ident)
        for child in dependents[ident]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", MISSING))
        order = topo_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    by_id = {row["id"]: row for row in changes}
    known = set(by_id)
    if not applied <= known:
        return failure("unknown-dependency")

    if request.get("action") == "rollback":
        emitted = [ident for ident in reversed(order) if ident in applied]
    else:
        emitted = [ident for ident in order if ident not in applied]
        units = sum(by_id[ident]["units"] for ident in emitted)
        if units > budget:
            return failure("budget-exceeded")
    units = sum(by_id[ident]["units"] for ident in emitted)
    return {"status": "ok", "actions": emitted, "units": units}

