"""Validate release policy before computing actions."""

ENVIRONMENTS = {"staging", "production"}
ACTIONS = {"plan", "rollback"}

# G2: this release is staging-only. Both plan and rollback are frozen.
FROZEN_ENVIRONMENTS = {"production"}

# G2: staging plans are capped at this many units regardless of the request.
STAGING_PLAN_LIMIT = 3


class PolicyError(ValueError):
    pass


def is_frozen(request):
    """True when the request targets an environment frozen for every action.

    Checked before any budget or change validation so a malformed graph still
    reports the freeze instead of a graph, budget or action error.
    """
    environment = request.get("environment")
    return isinstance(environment, str) and environment in FROZEN_ENVIRONMENTS


def _valid_environment(request):
    environment = request.get("environment")
    return isinstance(environment, str) and environment in ENVIRONMENTS


def limit_for(request):
    if not _valid_environment(request):
        raise PolicyError("invalid-environment")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return budget


def effective_budget(request, budget):
    """Effective unit cap for a plan; rollback budget is validated but unused."""
    if request.get("action") == "plan" and request.get("environment") == "staging":
        return min(budget, STAGING_PLAN_LIMIT)
    return budget

