"""Compose policy and journal data into a plan.

This is the only module that assembles a result, and it depends on journal and
policy one-way (journal/policy never import back). Every decision that could
emit a partial action list is made here before any output is returned.
"""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, check_budget, limit_for


class PlanError(Exception):
    pass


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def order_changes(changes):
    """Return every change ID in deterministic dependency order.

    Edges are prerequisite -> dependent, built after deduplication, so a
    dependency on a collapsed duplicate still resolves to the surviving ID.

    Missing prerequisites and cycles both leave nodes unordered; they are told
    apart by checking targets first, because SPEC gives them different codes.
    A cycle reached only through unapplied changes still fails here: the order
    is computed over the *full* graph, not just the slice a plan would emit, so
    plan and rollback can never disagree about what is executable.

    The ready set is a heap of IDs, which makes the tie-break lexicographic
    among currently eligible changes (not a global sort): a later-alphabet ID
    becomes eligible the moment its last prerequisite is emitted.
    """
    for change in changes.values():
        for dep in change["depends_on"]:
            if dep not in changes:
                raise PlanError("unknown-dependency")
    dependents = {cid: [] for cid in changes}
    indegree = {}
    for cid, change in changes.items():
        indegree[cid] = len(change["depends_on"])
        for dep in change["depends_on"]:
            dependents[dep].append(cid)
    ready = [cid for cid, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for child in dependents[cid]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(changes):
        raise PlanError("dependency-cycle")
    return order


def retained_set(changes, applied, retain):
    """Return applied IDs a staging rollback must keep: retained closure (G2).

    `retain` is already known to be applied (journal read it), so this is a
    pure graph closure: starting from the retained IDs, walk prerequisite and
    keep every node reached that is in `applied`. Walking only through
    *applied* prerequisites matters -- an unapplied prerequisite was never
    released, so it cannot be un-released and must not widen the kept set
    (and emitting it would break G1's rollback-only-applied rule).

    Keeping ancestors is required for correctness, not politeness: a retained
    consumer still needs its library, so rolling the library back underneath
    it would leave the surviving release broken.

    The order comes from `changes`/`applied` only, never from the retain list's
    own order, so the emitted sequence stays the single deterministic reverse
    topological order and is reproducible across calls.
    """
    keep = set()
    stack = [cid for cid in retain]
    while stack:
        cid = stack.pop()
        if cid in keep or cid not in applied:
            continue
        keep.add(cid)
        stack.extend(changes[cid]["depends_on"])
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        limit = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        # Read inside the same guard as applied: retain is only meaningful
        # against a parsed journal, and any retain complaint must not leak a
        # partial action list.
        retain = read_retain(request, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    unknown = sorted(applied - set(changes))
    if unknown:
        # The journal claims a release that this request cannot describe, so
        # neither a plan nor a rollback of it can be computed safely.
        return failure("unknown-dependency")
    try:
        order = order_changes(changes)
    except PlanError as exc:
        return failure(str(exc))
    if request["action"] == "rollback":
        # G2 retention: drop the retained IDs and the applied prerequisites
        # they still need; everything else applied unwinds in the untouched
        # full reverse order. With no retain this is exactly G1 behavior.
        # The budget stays uncapped here (limit is None from policy), so a
        # surviving set never strands a half-reverted release.
        kept = retained_set(changes, applied, retain)
        actions = [cid for cid in reversed(order) if cid in applied and cid not in kept]
    else:
        # Applied entries stay in the order as barriers but emit nothing:
        # they already satisfy their dependents and cost no new budget.
        actions = [cid for cid in order if cid not in applied]
    units = sum(changes[cid]["units"] for cid in actions)
    try:
        check_budget(limit, units)
    except PolicyError as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

