        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
    return list(value)


def _field(row, name):
    """Read an optional field defaulting only when it is absent."""
    return row[name] if name in row else []


def _read_record(row):
    """Read one change record into its normalized metadata."""
    if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
            or not isinstance(row.get("component"), str) or not row["component"]
            or type(row.get("units")) is not int or row["units"] < 1):
        raise JournalError("invalid-change")
    depends_on = _read_id_list(_field(row, "depends_on"))
    return {"id": row["id"], "component": row["component"], "units": row["units"],
            "depends_on": depends_on}


def read_changes(records):
    """Validate change records and collapse identical duplicates.

    Equality covers id, component, units and the set of dependencies. Two
    records sharing an id but differing in any of those conflict.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        change = _read_record(row)
        key = change["id"]
        if key in changes:
            previous = changes[key]
            same = (previous["component"] == change["component"]
                    and previous["units"] == change["units"]
                    and set(previous["depends_on"]) == set(change["depends_on"]))
            if not same:
                raise JournalError("conflicting-change")
            continue
        changes[key] = change
    return [changes[key] for key in sorted(changes)]


def read_applied(applied):
    """Read the persisted release journal as a set of change IDs."""
    return set(_read_id_list(applied))


def check_references(changes, applied):
    """Reject graph targets and journal entries that name unknown changes."""
    known = {change["id"] for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in known:
            raise JournalError("unknown-dependency")


