    """Return the full deterministic topological order of change IDs.

    Among currently eligible changes the lexicographically smallest ID goes
    first, so the order depends only on the normalized graph.
    """
    depends_on = {change["id"]: set(change["depends_on"]) for change in changes}
    dependents = {change_id: [] for change_id in depends_on}
    for change_id, deps in depends_on.items():
        for dependency in deps:
            dependents[dependency].append(change_id)
    pending = {change_id: len(deps) for change_id, deps in depends_on.items() if deps}
    eligible = [change_id for change_id, deps in depends_on.items() if not deps]
    heapq.heapify(eligible)
    ordered = []
    while eligible:
        change_id = heapq.heappop(eligible)
        ordered.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(ordered) != len(depends_on):
        raise JournalError("dependency-cycle")
    return ordered

