"""JSON transport for the release planner.

Transport only: one JSON request in, one JSON object out. SPEC requires every
request -- including domain errors -- to exit normally, so this layer keeps the
process from dying on an unexpected internal error.
"""
import json
import sys

from planner import failure, plan as _plan


def dispatch(request):
    """Call the planner, converting unforeseen bugs into the strict envelope.

    Failure protection lives here because this is the last boundary before
    stdout: a bug in *any* lower module would otherwise print a traceback or
    exit non-zero, and callers branch on "stdout is one JSON object". Genuine
    resource exhaustion is not disguised as a domain error -- that process
    state is unrecoverable, so it is allowed to terminate.
    """
    try:
        return _plan(request)
    except (MemoryError, RecursionError):
        raise
    except Exception:
        # No partial actions may leak from a crash: report the strict shape.
        return failure("invalid-request")


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        # ValueError covers a malformed or empty body; TypeError covers a
        # non-text stdin stream.
        result = failure("invalid-json")
    else:
        # planner itself reports non-object requests as `invalid-request`;
        # dispatch only guards against bugs, not against input shape.
        result = dispatch(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

